"""Rebuild the standalone report from versioned aggregate evidence. No training."""
from pathlib import Path
import json,hashlib,html,statistics
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent
COMMIT='23c407336cb0432822cabbd933f29b018a2319d7'
BASE=f'https://github.com/ClariRZ/Experimentos-/blob/{COMMIT}/'
sources={}
def read(path):
 p=ROOT/path;sources[path]=hashlib.sha256(p.read_bytes()).hexdigest();return json.loads(p.read_text())
def cite(path,label='Fuente'):
 p=ROOT/path
 if p.is_file():sources[path]=hashlib.sha256(p.read_bytes()).hexdigest()
 return f'<a href="{BASE+path}" target="_blank" rel="noopener">{html.escape(label)} ↗</a>'
def money(x):return '—' if x is None else f'{x/1e6:+.3f}'.replace('.',',')
def number(x):return f'{x/1e6:.3f}'.replace('.',',')
e=read('informes/prompts_modelos_2019_2026-11-13/evidencia.json');models=[]
for m in e['models']:
 a=m['august'];o=m['october'];models.append({'version':m['version'],'arm':m['arm'],'control':m['base'],'columns':m['columns'],'august_delta':m['summary']['ensemble_delta'],'october_delta':o['summary']['ensemble_delta'] if o else None,'october_wins':o['summary']['wins'] if o and m['arm']!=m['base'] else None,'seeds':5,'rule':'Control' if m['arm']==m['base'] else ('Cumplió regla de agosto' if m['eligible'] else 'No cumplió regla de agosto'),'policy':'Agosto suavizado · cortes propios','source':m['source']+'/result.json'})
vs=read('HISTORIA_2019_01/v7/resultados/RESUMEN_VERIFICADO.json')
for x in vs:
 models.append({'version':'v7','arm':x['arm'],'control':'B0','august_delta':x['agosto']['delta'],'october_delta':x['octubre']['delta'],'october_wins':x['octubre']['wins'] if x['arm']!='B0' else None,'seeds':5,'rule':'Control' if x['arm']=='B0' else 'No equivale a promoción; ver contrastes','policy':'Puntual · contactos comunes','source':'HISTORIA_2019_01/v7/resultados/octubre/'+x['arm']+'/result_october.json'})
v8='HISTORIA_2019_01/v8/resultados/v8_20261115_021908_c48e9d/originales/'
s=read(v8+'evaluation_201909.json');o=read(v8+'evaluation_201910.json');fin=read(v8+'FINAL.json');policy=read(v8+'policy.json');config=read(v8+'config_frozen.json')
for arm in ['B0','R3','T4','RR4']:
 a=read(v8+arm+'/august.json');b=read(v8+'B0/august.json');chosen=read(v8+arm+'/chosen.json')
 models.append({'version':'v8','arm':arm,'control':'B0','august_delta':a['common']['gain']-b['common']['gain'],'september_delta':s[arm].get('ensemble_delta',0),'october_delta':o[arm].get('ensemble_delta',0),'october_wins':o[arm].get('wins'),'seeds':10,'rule':'Control' if arm=='B0' else 'Prometedor, inconcluso','policy':'Puntual · contactos comunes','source':v8+'evaluation_201910.json'})
 for month,rows in [(201909,s),(201910,o)]:
  r=rows[arm];assert r['gain']==1100000*r['hits']-27500*r['K'];assert r['K']==policy['k_august']*r['N']//policy['n_august']
  if arm!='B0':assert r['ensemble_delta']==r['gain']-rows['B0']['gain'];assert statistics.mean(r['seed_deltas'])==r['seed_delta_mean']
 assert len(a['seed_common'])==10
p2='HISTORIA_2019_01/v2/cierre_20261110/resultados/'
b2=read(p2+'B0/resultado_5.json');h2=read(p2+'B4/resultado_5.json');d2=[x['gain']['gain_smoothed']-y['gain']['gain_smoothed'] for x,y in zip(h2['seeds'],b2['seeds'])];assert sum(x>0 for x in d2)==5
assert round(statistics.mean(d2))==4913353
v3=read('HISTORIA_2019_01/v3/manifiestos/FINAL.json');assert v3['candidate']=='C0' and v3['octubre_abierto'] is False
versions=[
('v1','Encontrar una transformación útil','Marzo–junio · 20 semillas por iteración','Baseline con historia → resúmenes, inactividad, ratios personales y ranking. La iteración 003 fue elegida por AUC de agosto.','AUC del ensemble: 0,914136 → 0,915105; 16/20 diferencias de AUC favorables. Octubre económico quedó pendiente.','Se respetó la comparación contra el padre: la reoptimización 007 no reemplazó a 003.','Ratios de v1 ≠ relativos de v4/v6. Exportar predicciones de octubre no significa haber medido su ganancia.','Conservar la señal de ratios como antecedente; no presentarla como validación económica final.','HISTORIA_2019_01/README.md'),
('v2','Construir la historia básica','Marzo–junio · escalera RAW → B4','Se agregaron lags y deltas progresivamente; después, familias sobre B4. La pregunta inicial era si la historia supera a las variables actuales.','B4 superó RAW en +4,913 M de ganancia suavizada media de agosto; 5/5 semillas. No es el delta del ensemble (+5,073 M).','La escalera permitió identificar cuánto aportaba la historia básica.','Ganar contra RAW no demuestra ganar contra el baseline histórico de Ale. La familia de ratios no identificable no es una derrota experimental.','Separar en el relato la construcción del control de las mejoras posteriores sobre ese control.',p2+'B4/resultado_5.json'),
('v3','Intentar mejorar el control ya construido','C0/B4 · parámetros heredados · ampliación hasta 20 semillas','Se compararon ranking actual, historia de ranking, actividad y presencia. Se ampliaron señales iniciales de cinco a veinte semillas.','El cierre conservó C0. Reoptimización y diagnóstico temporal no se presupuestaron; octubre siguió cerrado.','No se promovió una señal inicial que no se sostuvo con más semillas.','Congelar hiperparámetros aísla un cambio bajo ese ajuste, pero puede perjudicar representaciones de distinto tamaño.','Distinguir «no mejoró con estos parámetros» de «esta familia no sirve».','HISTORIA_2019_01/v3/manifiestos/FINAL.json'),
('v4','Dar a cada familia su propio ajuste','Marzo–junio · 5 brazos · 75 ajustes','B0 + F1 (resúmenes), F3 (relativos), F4a (ranking actual), F4b (historia del ranking). Cada brazo tuvo diez trials y cinco semillas.','Ninguna familia pasó la regla original de AUC. F3 ganó económicamente en ambos meses; F1 logró +12,155 M de ensemble en octubre pero sólo 2/5 semillas favorables.','Se reoptimizó por brazo, con presupuesto comparable y corte congelado antes de octubre.','La semilla 101 participó tanto en búsqueda como en evaluación. Cortes propios mezclan ranking y política de contacto.','Conservar B0 según la regla original; documentar las ganancias como hallazgos económicos, sin reescribir la selección.','experimento_2026-11-13/README.md'),
('v5','Separar el paquete para entenderlo','Marzo–junio · 7 brazos · 105 ajustes','Se separaron promedio, mínimo, máximo y rango; se probó quitar deltas y se volvió a evaluar el paquete F1. Semillas finales distintas de búsqueda.','Promedio +3,987 M, mínimo +5,110 M y rango +4,182 M en agosto. F1 completo no pasó la regla. No hay octubre publicado de esta corrida.','La descomposición muestra que unir componentes no suma automáticamente sus ganancias.','Agosto fue el mismo mes utilizado para seleccionar. No se comprobó la causa de la pérdida al combinar.','No llamar inútiles a los resúmenes ni ganadores finales a los componentes. Redundancia, ajuste y azar son explicaciones posibles.','HISTORIA_2019_01/v5/resultados/entrenamiento_20261113_01/FINAL.json'),
('v6','Preguntar cuánta historia hace falta','Junio común · 11 brazos · 165 ajustes','Se compararon lags, resúmenes, relativos y tendencias con ventanas de 3, 4 y 6 observaciones. El control también entrenó sólo en junio.','R3, R4 y T4 cumplieron la regla de agosto y ganaron en octubre con 5/5 semillas. R6 obtuvo +16,060 M en octubre, pero había perdido agosto.','Igualar el calendario del control evitó confundir más historia con distintos clientes de entrenamiento.','Junio tiene 128.474 filas; no se puede trasladar ese efecto a marzo–junio. Más profundidad modifica también cobertura.','No elegir R6 por el mejor octubre posterior. Mantener R3/T4 como señales y no declarar una profundidad universalmente óptima.','HISTORIA_2019_01/v6/resultados/octubre_v6_01/INFORME.md'),
('v7','Volver a tres meses y probar complementariedad','Abril–junio · 10 brazos · 150 ajustes','Se compararon representaciones y dos híbridos; se fijó un presupuesto de contactos común y tres contrastes principales con ajuste por multiplicidad.','T4: +11 M en octubre, −1,1 M en agosto. R3: +7,7 M y +3,3 M. Los híbridos no superaron de forma concluyente a sus componentes.','Mejor separación de economía y cantidad de contactos; cinco semillas nuevas, bootstrap y verificaciones exactas antes de octubre.','La parada por disco llegó después del desarrollo; octubre se completó en otra ejecución. Los contrastes principales eran de híbridos, no todas las comparaciones con B0.','Preservar ambos cierres y no presentar a T4 como ganador confirmatorio por un contraste secundario.','HISTORIA_2019_01/v7/README.md'),
('v8','Cerrar con menos hipótesis y mejor selección','Abril–junio · 4 brazos · 144 ajustes','B0, R3, T4 y RR4. Veinte trials por brazo; top 3 confirmados con dos semillas; diez semillas finales nuevas. Septiembre mide persistencia y octubre el cierre económico.','T4: +3,3 M en septiembre y +11 M en octubre. R3 pierde septiembre; RR4 empata septiembre y pierde en la media por semilla de octubre. Los tres: prometedores, inconclusos.','Se redujo la cantidad de preguntas, se separaron semillas de búsqueda/confirmación/evaluación y se fijaron contactos comunes e intervalos ajustados.','Más rigor no crea un test nuevo: agosto, septiembre y octubre no deben tratarse como meses vírgenes. El intervalo ajustado de T4 incluye cero.','Cerrar la conclusión experimental sin buscar v9 por inercia. T4 puede ser alternativa exploratoria, no reemplazo automático del control.',v8+'FINAL.json')]
