subs={'TIMELINE':''.join(f'<a href="#{v[0]}">{v[0]}</a>' for v in versions),'CARDS':cards,'RR4':cite('HISTORIA_2019_01/v8/cierre_consolidado/scripts/rr4.py','Fórmulas RR4'),'V8ROWS':vs8,'SVG':svg,'V8SOURCE':cite(v8+'evaluation_201910.json','Octubre original'),'ROWS':rows,'SOURCES':''.join('<li>'+cite(p,l)+'</li>' for p,l in refs)}
